import{_ as i,C as n,o as s,c as a,ah as o,E as r}from"./chunks/framework.sPHStHqt.js";const v=JSON.parse('{"title":"Invoices","description":"","frontmatter":{},"headers":[],"relativePath":"subscriptions/invoices.md","filePath":"subscriptions/invoices.md","lastUpdated":1789630599000}'),c={name:"subscriptions/invoices.md"};function l(h,e,d,p,u,m){const t=n("ImagePopup");return s(),a("div",null,[e[0]||(e[0]=o('<h1 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h1><p>Every payment a subscriber makes is recorded here as an <strong>invoice</strong>. This is the operator&#39;s billing ledger — one row per charge, across every tenant on the platform.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to read the platform-wide invoice list</li><li>What each invoice status means</li><li>How to download an invoice as a PDF</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Invoices vs. quotes</p><p>Don&#39;t confuse these with a tenant&#39;s own <strong><a href="/super-admin/quotes">Quotes</a></strong>. A quote is a sales document a tenant sends <em>their</em> customer. An invoice here is what a tenant pays <em>you</em> for their subscription.</p></div><h2 id="the-invoice-list" tabindex="-1">The invoice list <a class="header-anchor" href="#the-invoice-list" aria-label="Permalink to &quot;The invoice list&quot;">​</a></h2><p>Open <strong>Subscription → Invoices</strong>.</p>',6)),r(t,{src:"/images/invoices/invoices-grid.png",alt:"Invoices list"}),e[1]||(e[1]=o('<p>Each row shows:</p><ul><li><strong>Increment Id</strong> — the invoice number, e.g. <code>INV-0001</code>.</li><li><strong>Amount</strong> — the total charged.</li><li><strong>Payment Method</strong> — how it was paid, e.g. <strong>Stripe</strong>.</li><li><strong>Company Name</strong> — the subscriber the invoice belongs to.</li><li><strong>Company Email</strong> — their account address.</li><li><strong>Company Domain</strong> — their CRM address.</li><li><strong>Invoice Status</strong> — <strong>Active</strong> for a settled invoice, <strong>InActive</strong> otherwise.</li><li><strong>Created At</strong> — when the invoice was raised.</li></ul><p>Use <strong>Search</strong> to find an invoice by number or company, and <strong>Filter</strong> to narrow by status.</p><h2 id="downloading-an-invoice" tabindex="-1">Downloading an invoice <a class="header-anchor" href="#downloading-an-invoice" aria-label="Permalink to &quot;Downloading an invoice&quot;">​</a></h2><p>The download icon in the <strong>Actions</strong> column generates a PDF of the invoice — <code>Invoice_INV-0001_2026-09-09.pdf</code> — with the tenant&#39;s company details, the plan, and the amount. Hand it to a tenant who needs it for their own bookkeeping, or keep it for your records.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A subscriber can also download their own invoices from inside their workspace, and you can re-send the latest one to them from the <a href="/subscriptions/subscribers">subscriber detail view</a>.</p></div><h2 id="where-invoices-come-from" tabindex="-1">Where invoices come from <a class="header-anchor" href="#where-invoices-come-from" aria-label="Permalink to &quot;Where invoices come from&quot;">​</a></h2><p>An invoice is created automatically whenever a subscriber pays — on first purchase and again on every renewal. You don&#39;t raise invoices by hand; they follow the subscription. To change what a tenant is billed, edit the <a href="/subscriptions/plan-management">plan</a> they&#39;re on, which takes effect at their next renewal.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>See who these invoices belong to → <a href="/subscriptions/subscribers">Subscribers</a></li><li>Understand how billing looks from the tenant&#39;s side → <a href="/tenants/billing-and-invoices">Billing &amp; Invoices</a></li><li>Connect the payment gateway that settles them → <a href="/settings/configuration">Configuration</a></li></ul>',10))])}const b=i(c,[["render",l]]);export{v as __pageData,b as default};
